def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'

    opp_d = sum(1 for a, b in history if b == 'D')
    my_d = sum(1 for a, b in history if a == 'D')
    recent = history[-8:] if n >= 8 else history
    r_opp_d = sum(1 for a, b in recent if b == 'D')
    r_opp_c = len(recent) - r_opp_d
    r_my_d = sum(1 for a, b in recent if a == 'D')

    last_my, last_opp = history[-1]

    remaining = 100 - n

    # If opponent is nearly always defecting, minimize losses
    if opp_d >= n - 1 and n >= 6:
        if remaining <= 3:
            return 'D'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # If opponent is almost purely cooperative, cooperate and exploit late lightly
    if opp_d == 0:
        if remaining <= 4:
            return 'D'
        if n >= 20 and n % 13 == 0:
            return 'D'
        return 'C'

    # If recent window is heavily cooperative, preserve mutual cooperation
    if r_opp_d == 0:
        if remaining <= 3:
            return 'D'
        # occasional small probe to catch pure cooperators, but not too near end
        if remaining > 10 and n >= 15 and n % 17 == 0:
            return 'D'
        return 'C'

    # Endgame: take extra points when opponent is likely to cooperate
    if remaining <= 2:
        if r_opp_d <= 1 and opp_d * 3 <= n:
            return 'D'
        return 'C'

    if remaining <= 5:
        if r_opp_d <= 1 and opp_d <= max(2, n // 5):
            return 'D'
        if last_opp == 'D' and r_opp_d >= 2:
            return 'D'
        return 'C'

    # Opponent just cooperated: usually cooperate, but retaliate sharply if they
    # have been defecting a lot, and punish clusters of recent defection.
    if last_opp == 'C':
        if r_opp_d >= 3 and r_opp_c <= 1:
            return 'D'
        if opp_d * 2 > n and r_opp_d >= 2:
            return 'D'
        # If we just defected and they cooperated, return to cooperation
        if last_my == 'D':
            return 'C'
        return 'C'

    # Opponent just defected.
    # If they are mostly cooperative with rare defections, retaliate briefly
    # then forgive to restore mutual cooperation.
    if opp_d * 3 <= n:
        if r_opp_d >= 2:
            return 'D'
        # one-round punishment for isolated defection, then cooperate
        if last_my == 'C':
            return 'D'
        return 'C'

    # Moderate/high defection opponent: retaliate, but forgive periodically
    if r_opp_d >= 2:
        return 'D'

    # Single recent defection against mixed opponent: retaliate once but
    # be ready to forgive if they return to cooperation.
    if last_my == 'C':
        return 'D'
    if rng.random() < 0.4:
        return 'C'
    return 'D'
